const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("ledger.zig");
test "test_empty_ledger" {
const entries=[_]m.Entry{};
const out=try m.formatEntries(a,.usd,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       ",out);}
test "test_one_entry" {
const entries=[_]m.Entry{try m.createEntry("2015-01-01","Buy present",-1000)};
const out=try m.formatEntries(a,.usd,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)",out);}
test "test_credit_and_debit" {
const entries=[_]m.Entry{try m.createEntry("2015-01-02","Get present",1000),try m.createEntry("2015-01-01","Buy present",-1000)};
const out=try m.formatEntries(a,.usd,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)\n01/02/2015 | Get present               |       $10.00 ",out);}
test "test_final_order_tie_breaker_is_change" {
const entries=[_]m.Entry{try m.createEntry("2015-01-01","Something",0),try m.createEntry("2015-01-01","Something",-1),try m.createEntry("2015-01-01","Something",1)};
const out=try m.formatEntries(a,.usd,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Something                 |       ($0.01)\n01/01/2015 | Something                 |        $0.00 \n01/01/2015 | Something                 |        $0.01 ",out);}
test "test_overlong_description_is_truncated" {
const entries=[_]m.Entry{try m.createEntry("2015-01-01","Freude schoner Gotterfunken",-123456)};
const out=try m.formatEntries(a,.usd,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Freude schoner Gotterf... |   ($1,234.56)",out);}
test "test_euros" {
const entries=[_]m.Entry{try m.createEntry("2015-01-01","Buy present",-1000)};
const out=try m.formatEntries(a,.eur,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      (€10.00)",out);}
test "test_dutch_locale" {
const entries=[_]m.Entry{try m.createEntry("2015-03-12","Buy present",123456)};
const out=try m.formatEntries(a,.usd,.nl_nl,&entries);defer a.free(out);try t.expectEqualStrings("Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |   $ 1.234,56 ",out);}
test "test_dutch_locale_and_euros" {
const entries=[_]m.Entry{try m.createEntry("2015-03-12","Buy present",123456)};
const out=try m.formatEntries(a,.eur,.nl_nl,&entries);defer a.free(out);try t.expectEqualStrings("Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |   € 1.234,56 ",out);}
test "test_dutch_negative_number_with_3_digits_before_decimal_point" {
const entries=[_]m.Entry{try m.createEntry("2015-03-12","Buy present",-12345)};
const out=try m.formatEntries(a,.usd,.nl_nl,&entries);defer a.free(out);try t.expectEqualStrings("Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |    $ -123,45 ",out);}
test "test_american_negative_number_with_3_digits_before_decimal_point" {
const entries=[_]m.Entry{try m.createEntry("2015-03-12","Buy present",-12345)};
const out=try m.formatEntries(a,.usd,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       \n03/12/2015 | Buy present               |     ($123.45)",out);}
test "test_multiple_entries_on_same_date_ordered_by_description" {
const entries=[_]m.Entry{try m.createEntry("2015-01-01","Get present",1000),try m.createEntry("2015-01-01","Buy present",-1000)};
const out=try m.formatEntries(a,.usd,.en_us,&entries);defer a.free(out);try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)\n01/01/2015 | Get present               |       $10.00 ",out);}
